package cn.mop.api;

import cn.mop.domain.DomainException;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionTemplate.Item;
import cn.mop.domain.inspection.InspectionWorksheet.Observation;
import cn.mop.domain.inspection.InspectionWorksheet.Result;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class InspectionWorksheetContentTest {
    final UUID tenant=UUID.fromString("7a000000-0000-4000-8000-000000000001"),asset=UUID.fromString("7a000000-0000-4000-8000-000000000002"),templateId=UUID.fromString("7a000000-0000-4000-8000-000000000003");
    InspectionWorksheet sheet(){var definition=new InspectionTemplate("router","合成",List.of(new Item("a","bc","d",null)));return InspectionWorksheet.empty(tenant,asset,"合成设备",InspectionTemplate.Snapshot.capture(tenant,templateId,1,definition));}
    InspectionWorksheetContent content(){return new InspectionWorksheetContent(sheet(),null);}
    Observation observation(Result result,String note){return new Observation(result,note,List.of());}
    @Test void independentPythonGoldenBindsIdentityFrozenTemplateAndUnknownTime(){assertEquals("e73e9cae6546cd2b16f017f1bfb26c6838d14e38a371ad743287ea2e95cd9ba4",content().fingerprint());assertNull(content().reportedPerformedAt());assertEquals("NOT_PROVIDED",content().timeSource());}
    @Test void noEnteredObservationIsNotTheSameAsExplicitManualNormal(){var normal=sheet().record("a",observation(Result.NORMAL,null));assertNotEquals(content().fingerprint(),new InspectionWorksheetContent(normal,null).fingerprint());assertEquals(1,content().worksheet().summary().unanswered());assertEquals(0,normal.summary().unanswered());assertFalse(new InspectionWorksheetContent(normal,null).reportPublishable());}
    @Test void nullEmptyAndOriginalWhitespaceNotesHaveDifferentFingerprints(){var nullNote=new InspectionWorksheetContent(sheet().record("a",observation(Result.ATTENTION,null)),null);var empty=new InspectionWorksheetContent(sheet().record("a",observation(Result.ATTENTION,"")),null);var space=new InspectionWorksheetContent(sheet().record("a",observation(Result.ATTENTION," ")),null);assertNotEquals(nullNote.fingerprint(),empty.fingerprint());assertNotEquals(empty.fingerprint(),space.fingerprint());}
    @Test void resultChangesAreBoundIntoTheContent(){Set<String> hashes=new HashSet<>();for(var result:Result.values())hashes.add(new InspectionWorksheetContent(sheet().record("a",observation(result,"same note")),null).fingerprint());assertEquals(3,hashes.size());}
    @Test void observationMapIterationCannotAlterCanonicalOrder(){var definition=new InspectionTemplate("router","合成",List.of(new Item("a","组","一",null),new Item("b","组","二",null)));var snapshot=InspectionTemplate.Snapshot.capture(tenant,templateId,1,definition);Map<String,Observation> first=new LinkedHashMap<>();first.put("a",observation(Result.NORMAL,null));first.put("b",observation(Result.REQUIRES_ACTION,"说明"));Map<String,Observation> reversed=new LinkedHashMap<>();reversed.put("b",first.get("b"));reversed.put("a",first.get("a"));assertEquals(new InspectionWorksheetContent(new InspectionWorksheet(tenant,asset,"设备",snapshot,first),null).fingerprint(),new InspectionWorksheetContent(new InspectionWorksheet(tenant,asset,"设备",snapshot,reversed),null).fingerprint());}
    @Test void changingTheFrozenTemplateVersionChangesBindingEvenWithSameDefinition(){var old=sheet();var next=new InspectionWorksheet(tenant,asset,old.assetName(),InspectionTemplate.Snapshot.capture(tenant,templateId,2,old.template().definition()),old.observations());assertNotEquals(content().fingerprint(),new InspectionWorksheetContent(next,null).fingerprint());assertEquals(1,old.template().version());}
    @Test void assetIdNameAndTemplateIdentityAreNotInterchangeable(){var old=sheet();var renamed=new InspectionWorksheet(tenant,asset,"其他设备名称",old.template(),Map.of());var otherAsset=new InspectionWorksheet(tenant,UUID.randomUUID(),old.assetName(),old.template(),Map.of());var otherTemplate=new InspectionWorksheet(tenant,asset,old.assetName(),InspectionTemplate.Snapshot.capture(tenant,UUID.randomUUID(),1,old.template().definition()),Map.of());for(var value:List.of(renamed,otherAsset,otherTemplate))assertNotEquals(content().fingerprint(),new InspectionWorksheetContent(value,null).fingerprint());}
    @Test void tenantIdentityIsPartOfTheCanonicalContent(){var old=sheet();var other=UUID.randomUUID();var moved=new InspectionWorksheet(other,asset,old.assetName(),InspectionTemplate.Snapshot.capture(other,templateId,1,old.template().definition()),Map.of());assertNotEquals(content().fingerprint(),new InspectionWorksheetContent(moved,null).fingerprint());}
    @Test void explicitEpochTimeIsDifferentFromUnknownAndPreEpochMillisAreExact(){var epoch=new InspectionWorksheetContent(sheet(),Instant.EPOCH);assertNotEquals(content().fingerprint(),epoch.fingerprint());assertEquals("SELF_REPORTED_TIME",epoch.timeSource());var before=new InspectionWorksheetContent(sheet(),Instant.parse("1969-12-31T23:59:59.999Z"));assertNotEquals(epoch.fingerprint(),before.fingerprint());assertEquals(-1,before.reportedPerformedAt().toEpochMilli());}
    @Test void missingTimeNeverBecomesTheRecordingClock(){var value=content();value.requireNotFuture(Instant.parse("2026-10-04T09:00:00Z"));assertNull(value.reportedPerformedAt());assertEquals("SELF_REPORTED_UNVERIFIED",value.verificationStatus());}
    @Test void futureSelfReportedPerformanceFailsAgainstTheSuppliedActualClock(){var now=Instant.parse("2026-10-04T09:00:00.123Z");assertDoesNotThrow(()->new InspectionWorksheetContent(sheet(),now).requireNotFuture(now));assertDoesNotThrow(()->new InspectionWorksheetContent(sheet(),now.minusMillis(1)).requireNotFuture(now));var error=assertThrows(DomainException.class,()->new InspectionWorksheetContent(sheet(),now.plusMillis(1)).requireNotFuture(now));assertEquals("INSPECTION_TIME_IN_FUTURE",error.code);}
    @Test void timestampRangeAndSubMillisecondTruncationAreNotSilentlyAccepted(){for(var time:List.of(Instant.parse("0000-12-31T23:59:59.999Z"),Instant.parse("+10000-01-01T00:00:00Z"),Instant.EPOCH.plusNanos(1)))assertThrows(DomainException.class,()->new InspectionWorksheetContent(sheet(),time));assertThrows(DomainException.class,()->content().requireNotFuture(null));assertThrows(DomainException.class,()->new InspectionWorksheetContent(null,null));assertDoesNotThrow(()->new InspectionWorksheetContent(sheet(),Instant.parse("0001-01-01T00:00:00Z")));assertDoesNotThrow(()->new InspectionWorksheetContent(sheet(),Instant.parse("9999-12-31T23:59:59.999Z")));}
    @Test void unverifiedEvidenceReferencesAffectDigestButNeverGrantAccess(){var id=UUID.randomUUID();var with=new InspectionWorksheetContent(sheet().record("a",new Observation(Result.ATTENTION,null,List.of(id))),null);var without=new InspectionWorksheetContent(sheet().record("a",new Observation(Result.ATTENTION,null,List.of())),null);assertNotEquals(with.fingerprint(),without.fingerprint());assertEquals("REFERENCES_NOT_VERIFIED",with.worksheet().observations().get("a").evidenceStatus());assertFalse(with.reportPublishable());}
    @Test void returnedBytesAreIndependentAndContentRemainsImmutable(){var value=content();String hash=value.fingerprint();byte[] bytes=value.canonicalBytes();Arrays.fill(bytes,(byte)0);assertEquals(hash,value.fingerprint());assertNotEquals(0,value.canonicalBytes()[3]);}
    @Test void maximumAllowedNotesAndReferencesStayWithinTechnicalEncodingBound(){var items=new ArrayList<Item>();var answers=new LinkedHashMap<String,Observation>();for(int i=0;i<100;i++){String key="item_"+i;items.add(new Item(key,"组","项",null));var evidence=new ArrayList<UUID>();for(int j=0;j<10;j++)evidence.add(UUID.randomUUID());answers.put(key,new Observation(Result.ATTENTION,"😀".repeat(3000),evidence));}var snapshot=InspectionTemplate.Snapshot.capture(tenant,templateId,1,new InspectionTemplate("custom","合成上限",items));var value=new InspectionWorksheetContent(new InspectionWorksheet(tenant,asset,"合成设备",snapshot,answers),Instant.EPOCH);assertTrue(value.canonicalBytes().length>1_200_000);assertTrue(value.canonicalBytes().length<=InspectionWorksheetContent.MAX_CANONICAL_BYTES);assertEquals(100,value.worksheet().summary().answered());assertFalse(value.reportPublishable());}
}
